var gcMetricsAggregator = require("./GcMetricsAggregator");
const GC_TYPES = {
  1: "Scavenge",
  2: "MarkSweepCompact",
  4: "IncrementalMarking",
  8: "ProcessWeakCallbacks",
  3: "All", // Node v4 and earlier only have Scavenge and MarkSweepCompact.
  15: "All"
};
class GcAggregatedStats {
  constructor() {
    this.reset();
  }
  aggregateStats(stats) {
    let gcType = GC_TYPES[stats.gctype];
    if (!this.gcStats.get(gcType)) {
      this.gcStats.set(gcType, new gcMetricsAggregator());
    }
    let gcMetricsAggs = this.gcStats.get(gcType);
    gcMetricsAggs.addToExistingMetricData(stats);
    this.gcStats.set(gcType, gcMetricsAggs);
  }
  getAsJsonArray() {
    let gcData = [];
    this.gcStats.forEach(function (value, key) {
      //Below code not used for now as cmtools code check in dist/GCAggregatedStats.js Don't make functions within a loop (Rule:no-loop-func) for _objectSpread fn
      //let jsonGcData = { ...value.getAsJson() }; //deep copy of gcMetricsAggregator
      let jsonGcData = JSON.parse(JSON.stringify(value.getAsJson()));
      jsonGcData.name = key;
      gcData.push(jsonGcData);
    });
    return gcData;
  }
  reset() {
    this.gcStats = new Map();
  }
}
module.exports = GcAggregatedStats;
